"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import os
import re

VERSION_RE = re.compile(r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$")
SUBJECT_RE = re.compile(r"^(?P<type>[a-z]+)(?:\((?P<scope>[^()]*)\))?(?P<bang>!)?:(?P<desc>.*)$")

SECTION_NAMES = ("Breaking changes", "Features", "Fixes", "Performance")


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


def _parse_version(previous_version: str) -> tuple[int, int, int]:
    match = VERSION_RE.match(previous_version)
    if not match:
        raise CommitError(f"invalid version: {previous_version!r}")
    return int(match.group(1)), int(match.group(2)), int(match.group(3))


def _is_breaking_body(body: str) -> bool:
    for line in body.splitlines():
        stripped = line.strip()
        if stripped.startswith("BREAKING CHANGE:") or stripped.startswith("BREAKING-CHANGE:"):
            return True
    return False


def _parse_commit(commit: str):
    subject_part, sep, body_part = commit.partition("\n\n")
    subject = subject_part.strip()
    if "\n" in subject:
        return None
    match = SUBJECT_RE.fullmatch(subject)
    if not match:
        return None
    commit_type = match.group("type")
    scope = match.group("scope")
    if scope is not None:
        scope = scope.strip()
        if scope == "":
            scope = None
    desc = match.group("desc").strip()
    if desc == "":
        return None
    breaking = match.group("bang") is not None
    if not breaking and sep:
        breaking = _is_breaking_body(body_part)
    return commit_type, scope, breaking, desc


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    major, minor, patch = _parse_version(previous_version)

    parsed = [p for p in (_parse_commit(c) for c in commits) if p is not None]

    has_breaking = any(breaking for _, _, breaking, _ in parsed)
    has_feat = any(t == "feat" for t, _, _, _ in parsed)
    has_fix_or_perf = any(t in ("fix", "perf") for t, _, _, _ in parsed)

    if has_breaking:
        major, minor, patch = major + 1, 0, 0
    elif has_feat:
        minor, patch = minor + 1, 0
    elif has_fix_or_perf:
        patch = patch + 1

    new_version = f"{major}.{minor}.{patch}"

    sections: dict[str, set[tuple[str | None, str]]] = {name: set() for name in SECTION_NAMES}
    for commit_type, scope, breaking, desc in parsed:
        if breaking:
            section = "Breaking changes"
        elif commit_type == "feat":
            section = "Features"
        elif commit_type == "fix":
            section = "Fixes"
        elif commit_type == "perf":
            section = "Performance"
        else:
            continue
        sections[section].add((scope, desc))

    def sort_key(entry: tuple[str | None, str]):
        scope, desc = entry
        if scope is None:
            return (1, "", desc)
        return (0, scope, desc)

    parts = [f"## {new_version}\n"]
    for name in SECTION_NAMES:
        entries = sections[name]
        if not entries:
            continue
        parts.append("\n")
        parts.append(f"### {name}\n")
        parts.append("\n")
        for scope, desc in sorted(entries, key=sort_key):
            if scope is not None:
                parts.append(f"- **{scope}**: {desc}\n")
            else:
                parts.append(f"- {desc}\n")

    changelog_content = "".join(parts)
    version_content = f"{new_version}\n"

    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "CHANGELOG.md"), "w", encoding="utf-8") as f:
        f.write(changelog_content)
    with open(os.path.join(out_dir, "version.txt"), "w", encoding="utf-8") as f:
        f.write(version_content)
